MultiLanguageSpellData['ru'][168280] = {name = "Усиление", additional_info = "Радиус действия: 45 м\nПрименение: 2 сек\n[q]Усиливает находящегося рядом союзника, увеличивая наносимый им урон и восполняемое им здоровье. По мере снижения запаса здоровья заклинателя эффект усиливается."}
MultiLanguageSpellData['ru'][168281] = {name = "Активировать забытый подзарядник", additional_info = "Радиус действия: 10 м\nМгновенное действие\nИнгредиенты:\nСердечник\n[q]Активировать поврежденного стража араккоа с помощью сердечника. Страж будет следовать за вами и помогать вам в бою.\n\n Вы расходуете один сердечник."}
