MultiLanguageSpellData['ru'][168289] = {name = "Archaeology Template Spell", additional_info = "Применение: 2 сек\n[q]Хотя богомолы используют ветрошерсть и императорский шелк, предпочтение они отдают нетканым материалам, созданным из крыльев насекомых, включая их собственные. Это знамя создано из такого материала."}
MultiLanguageSpellData['ru'][168290] = {name = "Топор клана Северного Волка с отметинами клыков", additional_info = "Применение: 2 сек 5\n[q]Чтобы доказать свое право на место в клане Северного Волка, каждый орк должен в одиночку выполнить задание – подружиться с диким северным волком. Не всем это удается, но у счастливчиков появляется верный спутник на всю жизнь."}
MultiLanguageSpellData['ru'][168291] = {name = "Клык с семейной историей клана Северного Волка", additional_info = "Применение: 2 сек 5\n[q]В ходе ритуала инициации орк из клана Северного Волка должен убить морозного вепря и вырезать столько имен предков, сколько поместится на самом крупном бивне зверя. Семейная история и традиции очень важны для орков клана Северного Волка, поэтому каждый год они охотятся на самых крупных морозных вепрей, чтобы сохранить генеалогию клана."}
MultiLanguageSpellData['ru'][168292] = {name = "Снегоступы из волчьей шкуры", additional_info = "Применение: 2 сек 5\n[q]В морозной пустыне Ледяного Ветра мало растительности, и поэтому клан Северного Волка добывает пропитание охотой. Эти снегоступы, сделанные из волчьих костей и шкур, помогают охотникам, преследующим добычу, идти по глубокому снегу."}
MultiLanguageSpellData['ru'][168293] = {name = "Барабаны клана Песни Войны", additional_info = "Применение: 2 сек 5\n[q]Воины клана Песни Войны привыкли брать врага стремительным натиском, повергая его в смятение и трепет. Их жуткий боевой клич и грохот барабанов уже вошли в легенду. Эти чудовищные барабаны сделаны из кожи талбуков, натянутой на черепа огров – они символизируют освобождение клана от гнета огрской империи."}
MultiLanguageSpellData['ru'][168294] = {name = "Свистящая гуделка", additional_info = "Применение: 2 сек 5\n[q]Гуделка – это небольшая деревяшка на конце длинной веревки. Орк вращает гуделку над головой, и та производит монотонное гудение, слышное издалека. Умельцы из клана Песни Войны вырезали на этом инструменте бороздки, чтобы он издавал не низкий гул, как у других кланов, а пронзительный свист."}
MultiLanguageSpellData['ru'][168295] = {name = "Церемониальная пика клана Песни Войны", additional_info = "Применение: 2 сек 5\n[q]Всадники клана Песни Войны никогда подолгу не задерживаются на одном месте. В лагере семейную палатку отмечают длинной пикой, воткнутой в землю. Пика часто украшается черепами убитых врагов. Этому образцу более ста лет, и на его древке выжжены названия нескольких важных битв."}
MultiLanguageSpellData['ru'][168296] = {name = "Кузнечный молот", additional_info = "Применение: 2 сек 5\n[q]Этот старый молот покрыт вмятинами и царапинами, однако вытравленные на нем символы клана Черной горы все еще отчетливо видны. Клан Черной горы первым среди орочьих кланов овладел искусством обработки черного железа, и по сей день его представители предпочитают дробящее оружие, храня память о своих знаменитых предках-кузнецах."}
MultiLanguageSpellData['ru'][168297] = {name = "Кузнечные мехи стихий", additional_info = "Применение: 2 сек 5\n[q]Первоначально орки клана Черной горы плавили руду и закаляли металл в древнем стихийном огне Дренора. С помощью этих мехов шаман может направить силу огненного духа прямо в горнило. Это позволяет оркам клана Черной горы возводить кузни в любых условиях."}
MultiLanguageSpellData['ru'][168298] = {name = "Бритва орка из клана Черной горы", additional_info = "Применение: 2 сек 5\n[q]Юные орки из клана Черной горы не стригут волос до совершеннолетия. После инициации их обривают наголо и выбирают для них ремесло, сменить которое они уже не смогут, поскольку все аспекты жизни в клане жестко регламентированы. Эта древняя бритва выкована из металла Черной горы и украшена самоцветами. Скорее всего, некая влиятельная семья много лет использовала ее в ходе ритуала инициации."}
MultiLanguageSpellData['ru'][168299] = {name = "Тяжелый топор", additional_info = "Применение: 2 сек 5\n[q]Воины клана Изувеченной Длани воспринимают свое имя буквально – каждый из них дробит собственную кисть многочисленными ударами, а затем отрезает ее. Обрубок прижигается, и к нему приделывают какое-нибудь оружие. Этот экземпляр похож на топор для разделки мяса; он достаточно тяжел, чтобы перерубить запястье с одного удара."}
MultiLanguageSpellData['ru'][168300] = {name = "Кривой кинжал", additional_info = "Применение: 2 сек 5\n[q]Орки из клана Изувеченной Длани калечат себя в честь победы над врагом. Самые знаменитые воины покрыты шрамами и пирсингом с ног до головы, и с возрастом становится трудно понять, какие из шрамов нанес враг, а какие – сам торжествующий орк."}
MultiLanguageSpellData['ru'][168301] = {name = "Шипастый рыболовный крюк", additional_info = "Применение: 2 сек 5\n[q]Этот рыболовный крюк длиной с руку больше похож на алебарду, а не на рыболовную снасть. Можно лишь предполагать, на каких морских чудовищ рассчитан такой крюк. Неудивительно, что большинство орков предпочитает такому \"рыболовству\" традиционную охоту."}
MultiLanguageSpellData['ru'][168302] = {name = "Окаменевший глаз в банке", additional_info = "Применение: 2 сек 5\n[q]Должно быть, этот хорошо сохранившийся глаз когда-то принадлежал вождю клана Кровавой Глазницы. Каждый, кто становится вождем этого клана, жертвует свой глаз, чтобы получить дар шаманского предвидения и узреть свою будущую смерть. Можно лишь представить себе, какие мрачные события лицезрел этот глаз."}
MultiLanguageSpellData['ru'][168303] = {name = "Церемониальные татуировочные иглы", additional_info = "Применение: 2 сек 5\n[q]Эти тщательно наточенные иглы сделаны из костей убитых врагов. Мистики клана Призрачной Луны часто набивают на своих телах тайные руны – это помогает им общаться с предками и духами стихий."}
MultiLanguageSpellData['ru'][168304] = {name = "Потрескавшийся костяной идол", additional_info = "Применение: 2 сек 5\n[q]Черный, словно ночное небо, идол – атрибут поклонения Бездне. Орки клана Призрачной Луны когда-то почитали ее, но затем старейшины клана запретили этот культ. Этот грубый идол, похоже, был наскоро вырезан из бивня огромного элекка, а затем покрашен и расписан сложными узорами."}
MultiLanguageSpellData['ru'][168305] = {name = "Талисман предков", additional_info = "Применение: 2 сек 5\n[q]Когда оркам клана Призрачной Луны нужно принять важное решение, их шаманы непременно обращаются за советом к духам предков. Талисманы и другие реликвии, которые играли важную роль в жизни предка, помогают шаману установить более прочную связь с ним."}
MultiLanguageSpellData['ru'][168306] = {name = "Фляга с горючей смазкой", additional_info = "Применение: 2 сек 5\n[q]Перед боем орки клана Пылающего Клинка смазывают мечи и топоры этой липкой, вонючей и крайне огнеопасной субстанцией. Хотя некоторые воины сами поджигают свое оружие, большинство предпочитает, чтобы оно воспламенилось от искр, вылетающих при неизбежном столкновении оружия с броней."}
MultiLanguageSpellData['ru'][168307] = {name = "Подвеска из зуба гронна", additional_info = "Применение: 2 сек 5\n[q]Громоборцы – лучшие на Дреноре охотники на крупного зверя. Уже много лет они объезжают диких зверей и охотятся на дичь и гроннов. Название их клана связано с легендой о древнем вожде, который в одиночку убил сильнейшего из гроннов на Громовой вершине."}
MultiLanguageSpellData['ru'][168308] = {name = "Предсказание Судного дня", additional_info = "Применение: 2 сек 5\n[q]На этой скрижали написано про \"конец времен\". Судя по тому, что вы можете разобрать в этих грубо нацарапанных разными авторами знаках, тут говорится не менее чем о семи противоречащих друг другу сценариях катастрофы, которая погубит всех обитателей Дренора. Странно, но здесь нарисовано четкое изображение пылающего молота – может, это как-то связано с кланом Сумеречного Молота?"}
MultiLanguageSpellData['ru'][168309] = {name = "Камень престолонаследия клана Каменного Молота", additional_info = "Применение: 2 сек 5\n[q]Огры живут небольшими кланами, во главе которых стоят вожди. Обычно вожди безжалостно уничтожают тех, кто покушается на их власть, но это никогда не останавливало претендентов. Клан Каменного Молота славится тем, что вожди в нем меняются невероятно часто. Судя по слоям засохшей крови, этот камень сыграл важную роль в смещении многих из них."}
MultiLanguageSpellData['ru'][168310] = {name = "Каменные оковы", additional_info = "Применение: 2 сек 5\n[q]Ограм без надобности застежки и замки на кандалах – они надевают на пленников цельные каменные браслеты. За много веков они отлично научились договариваться со стихией земли – и поэтому сейчас с легкостью стягивают каменные оковы, надетые на лодыжки, запястья и шеи рабов."}
MultiLanguageSpellData['ru'][168311] = {name = "Фигурка огра", additional_info = "Применение: 2 сек 5\n[q]Главное качество огров – это их размер. Неизвестный скульптор (как и большинство его соплеменников - огров) не смог выразить эту идею с помощью слов, но искусно отразил в изображении: копытень, которого огр держит над головой, свидетельствует о его силе, а большой живот скульптуры олицетворяет собой богатство."}
MultiLanguageSpellData['ru'][168312] = {name = "Пиктограмма", additional_info = "Применение: 2 сек 5\n[q]Обычно время для занятий каллиграфией находится только у элиты империи огров, но иногда и у обычного подданного появляется желание запечатлеть интересную историю в веках. Эта пиктограмма, похоже, рассказывает об особенно омерзительном кулинарном опыте."}
MultiLanguageSpellData['ru'][168313] = {name = "Щит гладиатора", additional_info = "Применение: 2 сек 5\n[q]Разногласия между ограми обычно приводят к насилию. Но в начале Эпохи порядка один хитроумный вождь приказал, чтобы все споры в его клане решались в поединках между рабами. Смертность среди его подданных упала, а в истории огров начался золотой период экспансии."}
MultiLanguageSpellData['ru'][168314] = {name = "Ступка и пестик", additional_info = "Применение: 2 сек 5\n[q]Огры любят демонстрировать свою мускулатуру и поэтому предпочитают носить минимум одежды. Чтобы вселять страх во врагов, они раскрашивают себя красками, растертыми с помощью этих инструментов. Эти ступка и пестик окрашены в желтый цвет; значит, их использовали воины клана Тяжелого Кулака.\nСтановится персональным при получении\n[q2]Использование: Тщательно упаковать найденный артефакт.\n[q]\"Этот артефакт уже записан в ваш журнал археологических находок. На вкладке \"Собранные артефакты\" вы можете найти его описание.\""}
MultiLanguageSpellData['ru'][168315] = {name = "Глаз Хар'гунна Слепого", additional_info = "Применение: 2 сек 5\n[q]Большинство огров рождается с двумя глазами, однако в каждом поколении можно найти несколько одноглазых. Почти во всех кланах одноглазых огров уважают и считают, что им суждены великие свершения. Один несчастливый одноглазый огр-маг потерял глаз в поединке и заменил его этим камнем размером с кулак – а впоследствии с удивлением обнаружил, что камень обладает волшебными свойствами."}
MultiLanguageSpellData['ru'][168316] = {name = "Каменная вставная челюсть", additional_info = "Применение: 2 сек 5\n[q]Огры сражаются очень безыскусно и часто получают столько же ран, сколько и наносят, надеясь победить за счет своей силы и стойкости. Эта зазубренная вставная челюсть – доказательство того, что по крайней мере один огр потерял в бою все зубы, но все равно победил."}
MultiLanguageSpellData['ru'][168317] = {name = "Упряжь для рилака", additional_info = "Применение: 2 сек 5\n[q]Один гениальный огр однажды подумал, что летать на рилаке будет, пожалуй, быстрее, чем ездить на верховых животных или ходить пешком. Это грубое седло с невероятным количеством узлов было бы вполне удобным для огра. Однако для подобной поездки понадобился бы рилак размером с небольшую гору. Вот почему никто и никогда не видел летающих огров."}
MultiLanguageSpellData['ru'][168318] = {name = "Стела с приказом императора", additional_info = "Применение: 2 сек 5\n[q]Эти осколки каменной стелы датируются несколькими веками до прибытия дренеев. На ней выбит приказ императора огров разорить несколько селений орков в наказание за нападения на горианские караваны рабов. Скорее всего, приказ был выполнен – ведь этих городов больше нет, а в честь жестокой расправы был воздвигнут памятный камень."}
MultiLanguageSpellData['ru'][168319] = {name = "[q3]Ножное кольцо короля-чародея", additional_info = "Применение: 2 сек 10\n[q]Имперские огры ревностно охраняют секреты магии, чтобы сохранить свое положение в правящей элите. Самые богатые из них украшают себя зачарованными украшениями и другими артефактами.\n[q3]Ножное кольцо короля-чародея\n[q7]Привязывается к отряду\nШея\n+3 к интеллекту\n+4 к выносливости\n[q2]+ 3 к критическому удару\n[q2]+ 2 к скорости\nТребуется"}
MultiLanguageSpellData['ru'][168320] = {name = "[q3]Боевой молот вождя клана Боевого Молота", additional_info = "Применение: 2 сек 10\n[q]Первый прорыв в области высоких технологий огры совершили, разработав концепцию прикрепления камня к очень длинной палке, что стало настоящим переворотом воинского искусства со времен прошлого изобретения: камня, зажатого в руке. Эта инновация вызвала раскол в обществе огров, который был преодолен только после того, как уже забытое первоначальное племя разделилось на кланы Боевого Молота и Тяжелого Кулака.\n[q3]Боевой молот вождя клана Боевого Молота\n[q7]Привязывается к отряду\nДвуручное Дробящее\nУрон: 10 - 14 Скорость 3.60\n(3.3 ед. урона в секунду)\n+5 к силе\n+7 к выносливости\n[q2]+ 5 к критическому удару\n[q2]+ 3 к скорости\nПрочность: 100 / 100\nТребуется"}
MultiLanguageSpellData['ru'][168321] = {name = "Ловец снов", additional_info = "Применение: 2 сек 5\n[q]Когда Терокк вернулся из изгнания, он был сломлен и не мог летать. Слухи о том, что на нем лежит проклятие, распространились среди араккоа словно лесной пожар, и это привело к появлению многочисленных амулетов и снадобий. Ловцы снов по-прежнему считаются главными талисманами; араккоа верят, что ночью проклятие застревает в сетях ловца и рассеивается в лучах утреннего солнца."}
MultiLanguageSpellData['ru'][168322] = {name = "Погребальная урна", additional_info = "Применение: 2 сек 5\n[q]Все араккоа стремятся после смерти попасть на небо к богине солнца Рухмар, поэтому предпочитают кремацию захоронению. Кто-то развеивает пепел мертвых, поднявшись в воздух, другие запечатывают его в богато украшенных урнах и хранят в усыпальницах."}
MultiLanguageSpellData['ru'][168323] = {name = "Свитки с указами", additional_info = "Применение: 2 сек 5\n[q]Эти обрывочные предложения, похоже, являются частью указа о введении военного положения и напоминают всем о том, что нужно тщательно следить за проявлениями проклятья у соседей и друзей."}
MultiLanguageSpellData['ru'][168324] = {name = "Солнечная сфера", additional_info = "Применение: 2 сек 5\n[q]Центральное место в культуре высших араккоа занимает поклонение Рухмар и солнцу. Сотни солнечных сфер рассеяны по Небесному Пути, и от них исходит неугасимый свет, так что араккоа даже в холодный и пасмурный день не лишены солнечного тепла."}
MultiLanguageSpellData['ru'][168325] = {name = "Солнечные часы", additional_info = "Применение: 2 сек 5\n[q]Этот покрытый изысканной гравировкой инструмент при правильной установке служит араккоа и солнечными часами, и календарем. Основание инструмента покрыто символами астрономических событий, многие из которых сопровождаются жуткими предостережениями. Стоит отметить, что этот инструмент туманно предсказал прибытие дренеев за сто лет до того, как это произошло."}
MultiLanguageSpellData['ru'][168326] = {name = "Маска жреца Когтя", additional_info = "Применение: 2 сек 5\n[q]Проклятые араккоа считают, что солнце покинуло их, и поэтому предпочитают днем прятаться в лесах или под навесами. Жрецы Когтя пошли еще дальше: они никогда не подставляют лицо солнечным лучам и всегда носят ритуальные маски, которые помогают им общаться с Анзу."}
MultiLanguageSpellData['ru'][168327] = {name = "Ловец снов изгоев", additional_info = "Применение: 2 сек 5\n[q]Изгнанные араккоа переделали этот ловец снов – теперь он не защищает от проклятия Сете, а захватывает крошечные частицы сущности исчезнувших богов. По слухам, прямо под Скеттисом расположен огромный, постоянно растущий водоворот энергии, который обещает подарить невиданное могущество любому, кто согласится слушать..."}
MultiLanguageSpellData['ru'][168328] = {name = "Апекситовый кристалл", additional_info = "Применение: 2 сек 5\n[q]В самых древних руинах Дренора можно найти останки цивилизации апекситов, чей расцвет относят к Эпохе порядка. Исчезли апекситы практически мгновенно и без следа. Появление Железной Орды напугало Приверженцев богини солнца, и они решили ускорить поиски апекситских артефактов."}
MultiLanguageSpellData['ru'][168329] = {name = "Иероглиф апекситов", additional_info = "Применение: 2 сек 5\n[q]Эта невероятно древняя и хрупкая каменная скрижаль описывает машину удивительной силы, которая якобы может подчинить себе энергию солнца."}
MultiLanguageSpellData['ru'][168330] = {name = "Свиток апекситов", additional_info = "Применение: 2 сек 5\n[q]Этот помятый футляр для свитков заржавел так, что не открыть, а текст свитка очень трудно разобрать даже после тщательного изучения. Похоже, это планы какого-то строения под названием \"Храм в небесах\". Действительно ли было построено столь удивительное здание, непонятно."}
MultiLanguageSpellData['ru'][168331] = {name = "[q3]Клюволом Терокка", additional_info = "Применение: 2 сек 10\n[q]Терокк отказался от традиционного оружия араккоа и выбрал эту дубинку как символ своего превращения из короля в еретика-изгоя. Много веков ходили слухи о том, что Терокк не отрезал провинившимся крылья в качестве наказания, как того требовала традиция, а просто проламывал дубинкой клювы всем, кто осмеливался ему перечить.\n[q3]Клюволом Терокка\n[q7]Привязывается к отряду\nОдноручное Дробящее\nУрон: 5 - 7 Скорость 2.60\n(2.3 ед. урона в секунду)\n+2 к [ловкости или силе]+3 к выносливости\n[q2]+ 2 к критическому удару\n[q2]+ 2 к искусности\nПрочность: 90 / 90\nТребуется"}
