MultiLanguageSpellData['ru'][178052] = {name = "Кровоизлияние", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Резкий удар, наносящий 25% урона от оружия. Увеличивает физический урон от эффектов кровотечения на 125. Действует в течение 10 удара:ударов или 15 сек. Длина серии приемов увеличивается на 1."}
