MultiLanguageSpellData['ru'][184906] = {name = "Неуловимые телодвижения", additional_info = "[q]Когда запас вашего здоровья упадет ниже 5 %, вы получите заряд эффекта \"Отвар железной шкуры\". \"Отвар железной шкуры\" также увеличивает наносимый урон на 1 %."}
