MultiLanguageSpellData['ru'][184908] = {name = "Разъяренное солнце", additional_info = "[q]С вероятностью 2 % вы без затрат ресурсов проведете дополнительный \"Удар восходящего солнца\" после использования \"Неистовых кулаков\", \"Нокаутирующего удара\" или \"Удара восходящего солнца\"."}
MultiLanguageSpellData['ru'][184909] = {name = "Усиливающийся свет", additional_info = "[q]При осуществлении лечения способностью \"Шок небес\" вы получите эффект \"Усиливающийся свет\", на 7 % повышающий эффективность исцеления от вашего следующего заклинания \"Свет небес\" или \"Вспышка Света\", примененного в течение последующих 6 сек."}
