MultiLanguageSpellData['ru'][196470] = {name = "Сосуд из фиолетового стекла", additional_info = "Применение: 2 сек 5\n[q]Высокорожденные питали страсть к лиловому цвету еще со времен, предшествовавших Войне древних. Стеклянные чаши тогда были в широком обиходе; чего только в них ни хранили – начиная от круп и заканчивая золотыми слитками."}
MultiLanguageSpellData['ru'][196471] = {name = "Амулет из инертного силового камня", additional_info = "Применение: 2 сек 5\n[q]Среди высокорожденных бытовало суеверие, будто бы силовой камень способен приносить удачу. Амулеты из силового камня пользовались огромной популярностью у сельских жителей, нерадивых учеников и тех, кто мечтал когда-нибудь выбраться из грязи в князи."}
MultiLanguageSpellData['ru'][196472] = {name = "Склянка с мировином", additional_info = "Применение: 2 сек 5\n[q]Слово \"мировино\" у древних высокорожденных означало просто-напросто \"яд\". Пролежав в земле десяток тысяч лет, эта смертоносная жидкость утратила токсичность и теперь может оказать лишь легкий опьяняющий эффект."}
MultiLanguageSpellData['ru'][196473] = {name = "Довоенный гобелен высокорожденных", additional_info = "Применение: 2 сек 5\n[q]Гобелены, сотканные еще до заключения договора между королевой Азшарой и демонами, отличались уникальной техникой изготовления, при которой на один стежок в одном направлении приходилось по два в другом. Впоследствии этой технологией уже никогда не пользовались."}
MultiLanguageSpellData['ru'][196474] = {name = "Аристократический ножик для разрезания бумаги", additional_info = "Применение: 2 сек 5\n[q]Этот нож для вскрытия писем (как, впрочем, и все такие ножи) никогда не употреблялся по назначению, но зато его можно было спокойно носить при себе в качестве орудия убийства, когда иметь при себе обычный кинжал было, мягко говоря, неуместно."}
MultiLanguageSpellData['ru'][196475] = {name = "Первый барабан", additional_info = "Применение: 2 сек 5\n[q]Таурены-охотники обычно увековечивали день, когда им удавалось добыть своего первого зверя, в виде барабана, сделанного из его шкуры. Чаще всего такие барабаны делались из заячьих или лисьих шкур. Как правило, охотник не расставался с этим барабаном до конца своих дней."}
MultiLanguageSpellData['ru'][196476] = {name = "Рыболовный крючок из лосиной кости", additional_info = "Применение: 2 сек 5\n[q]Основным материалом для изготовления рыболовных крючков в те времена служила лосиная кость. Она была достаточно твердой, чтобы на ней можно было делать насечки, и в то же время обладала необходимой гибкостью, иначе бы в пасти особо крупной рыбы крючок бы просто сломался. Многие рыбаки изготавливали крючки особо причудливой формы и верили, что они принесут им удачу."}
MultiLanguageSpellData['ru'][196477] = {name = "Отшлифованный вручную огнекамень", additional_info = "Применение: 2 сек 5\n[q]Согласно обычаю, вдовы, дети и внуки умерших носили при себе огнекамни от погребального костра, на котором был предан огню ушедший в лучший мир член их семейства. Считалось, что если потереть такой камень в трудную минуту, он воскресит в памяти воспоминания о дорогом сердцу родственнике и придаст бодрости духа и храбрости."}
MultiLanguageSpellData['ru'][196478] = {name = "Дрогбарская камнедробилка", additional_info = "Применение: 2 сек 5\n[q]Большинство дрогбаров предпочитало необработанные самоцветы с острыми гранями, но были и те, кому по душе были камни более правильной формы. Дрогбары не пользовались общепринятыми инструментами для огранки камней – вместо этого самоцветы обтирались в специальной каменной ручной мельничке, которую нужно было крутить на протяжении нескольких недель. Обычно такую работу выполняли слуги, рабы или провинившиеся дети."}
MultiLanguageSpellData['ru'][196479] = {name = "Лук Каменного леса", additional_info = "Применение: 2 сек 5\n[q]Плечи этого лука вырезаны из особо прочного дерева, твердого, как камень. Натянуть его практически нереально. Археологи до сих пор спорят, был ли этот лук таким изначально или же дерево окаменело со временем. В любом случае, судя по размеру и весу лука, можно предположить, что стрелять из такого оружия могли лишь самые сильные и опытные таурены-охотники."}
MultiLanguageSpellData['ru'][196480] = {name = "Чаша беса", additional_info = "Применение: 2 сек 5\n[q]Бесам тоже нужно пить, и большинство из них предпочитает всегда иметь при себе фляжку с любимым напитком. Существует гипотеза о том, что когда-то существовала древняя раса бесоподобных созданий, среди которых питьевые фляги считались священными, и этот обычай частично сохранился даже после того, как эта раса стала частью Легиона."}
MultiLanguageSpellData['ru'][196481] = {name = "Хроника на содранной коже", additional_info = "Применение: 2 сек 5\n[q]Разные демоны проводят свое время между битвами по-разному. Суккубы, например, обожают вести дневники, в которых расписывают свою повседневную жизнь. Эти записи обычно полны кошмарных подробностей, а \"бумагой\" для такого дневника, как правило, служит кожа, содранная с поверженного противника или пленника."}
MultiLanguageSpellData['ru'][196482] = {name = "Бесформенный абиссал", additional_info = "Применение: 2 сек 5\n[q]Ритуал призыва абиссала очень сложен и нередко завершается неудачей. При неудаче в мире обычно остается небольшая частица демона, пылающая яростью и отчаянием от своего бессилия. На полях древних сражений и по сей день остается немало таких камней."}
MultiLanguageSpellData['ru'][196483] = {name = "Сфера внутреннего хаоса", additional_info = "Применение: 2 сек 5\n[q]Хаос не является естественной стихией для всех демонов, и некоторым из них бывает непросто принять мировоззрение Пылающего Легиона. Таким демонам приходится носить при себе специальные зачарованные сферы, которые в нужный момент могут вызвать у них вспышку ярости – иначе что это за демон? Кто изготавливал такие сферы и из чего они сделаны, до сих пор остается неизвестным."}
MultiLanguageSpellData['ru'][196484] = {name = "Хауберк из зубов гончих", additional_info = "Применение: 2 сек 5\n[q]Большой кусок \"кольчужного\" нагрудника, целиком изготовленного из клыков псов-демонов. Острые концы зубов обращены вверх и вовнутрь, так что если надеть такой доспех, снять его будет уже невозможно – то есть, в принципе, возможно, но лишь ценой серьезных увечий."}
