MultiLanguageSpellData['ru'][198108] = {name = "Инерция", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Урсок совершает рывок к своей цели, нанося 2151 ед. физического урона игрокам на своем пути и отбрасывая их. Пораженные игроки получают на 500% больше урона от способности \" Инерция \" в течение 50 сек."}
MultiLanguageSpellData['ru'][198109] = {name = "Мощное столкновение", additional_info = "Мгновенное действие\n[q]Когда Урсок достигает выбранной цели, он наносит 9789 ед. физического урона всем игрокам. Сила этого эффекта уменьшается за каждого игрока, вставшего на пути Урсока во время его рывка."}
MultiLanguageSpellData['ru'][198110] = {name = "Морская порча", additional_info = "Радиус действия: 300 м\nМгновенное действие\n[q]Оскверняет цель, нанося 253 ед. урона от магии льда каждую секунду в течение 21 сек. При завершении действия ауры порча взрывается, нанося 850 ед. урона от магии льда всем игрокам."}
