MultiLanguageSpellData['ru'][204330] = {name = "Тотем гнева", additional_info = "Мгновенное действие\n[q]Вы призываете рядом с собой тотем на 15 сек. Тотем усиливает критический эффект наносящих урон и исцеляющих заклинаний союзников в радиусе (40 * 1 * 1 ) м на 15% на 15 сек."}
MultiLanguageSpellData['ru'][204331] = {name = "Тотем контрудара", additional_info = "[q0]Танки – PvP-талант 1 ряда\n{0.6% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 45 сек}\n[q]На 15 сек. призывает рядом с вами тотем.\n\n Когда противники в радиусе (20 * 1 * 1 ) м от тотема наносят прямой урон, тотем наносит им 100% этого урона."}
MultiLanguageSpellData['ru'][204332] = {name = "Тотем неистовства ветра", additional_info = "5% от базовой мана\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Призывает в указанной точке тотем прочностью 5 ед. на 1 мин. Если тотем уничтожают, \"Тотем неистовства ветра\" восстанавливается 30 сек.\n\n Тотем усиливает оружие союзников в радиусе 10 м от тотема, в результате чего при атаках они с 40%-й вероятностью проводят 3 дополнительные атаки, наносящие:дополнительных атак, наносящих по ([27.945% of Attack Power])% ед. физического урона."}
