MultiLanguageSpellData['ru'][205021] = {name = "Морозный луч", additional_info = "{2% от базовой мана} {Радиус действия: 40 м}\n{Направляемое (Применение:} 5 сек) {Восстановление: 1 мин}\n[q]Вы поддерживаете луч ледяной энергии, нанося противнику ([269.1% of Spell Power]) ед. урона от магии льда раз в 1 сек. и снижая его скорость передвижения на 60%. Время действия – 5 сек. Каждый раз, когда \"Морозный луч\" наносит урон, наносимый им урон и эффективность замедления увеличиваются на 10 %.\n\n Дает 2 эффекта:эффектов \"Ледяные пальцы\"."}
MultiLanguageSpellData['ru'][205022] = {name = "Волшебный фамилиар", additional_info = "[q]\"Чародейский интеллект\" призывает фамилиара, который атакует ваших противников и увеличивает ваш максимальный запас маны на 10% на 1 ч."}
MultiLanguageSpellData['ru'][205023] = {name = "Поджигание", additional_info = "[q]\"Огненный шар\" и \"Огненная глыба\" поражают цель эффектом \"Поджигание\", дополнительно наносящим ([7.03868% of Spell Power]) ед. урона от огня в течение 8 сек.\n\n Противники, на которых действует \"Поджигание\" или \"Воспламенение\", с вероятностью 15% могут вспыхнуть, нанеся ([6.28762% of Spell Power]) ед. урона от огня находящимся рядом противникам."}
MultiLanguageSpellData['ru'][205024] = {name = "Одинокая зима", additional_info = "[q]Заменяет Призыв элементаля воды\n[q]\"Ледяная стрела\", \"Ледяное копье\" и \"Шквал\" наносят на 15% больше урона."}
MultiLanguageSpellData['ru'][205025] = {name = "Величие разума", additional_info = "{Мгновенное действие} {Восстановление: 45 сек}\n[q]Позволяет применить 2 следующие \"Чародейские вспышки\":следующих \"Чародейских вспышек\" мгновенно ."}
