MultiLanguageSpellData['ru'][205027] = {name = "Пробирающий холод", additional_info = "[q]Каждый раз, когда вы пытаетесь заморозить цель, вы на 8 сек. получаете эффект \"Пробирающий холод\", суммирующийся до 10 раз. Каждый эффект увеличивает наносимый вами урон от заклинаний на 0.5%."}
