MultiLanguageSpellData['ru'][205646] = {name = "Удар оскверненной души", additional_info = "Дистанция ближнего боя\nПрименение: 2 сек\n[q]Наносит урон от магии Хаоса противникам в секторе перед собой на расстоянии до 10 м, и снижает эффективность получаемого ими исцеления на 50% в течение 8 сек."}
