MultiLanguageSpellData['ru'][206474] = {name = "Алчущий рой", additional_info = "Радиус действия: 300 м\nМгновенное действие\n[q]Тихондрий насылает волну хаотической магии на всех игроков, пораженных \"Трупным заражением\". Этот эффект наносит 3109 ед. урона от темной магии всем игрокам, находящимся на одной линии между Тихондрием и каждой из его целей. Кроме того, на всех пораженных игроков также накладывается \"Трупное заражение\"."}
MultiLanguageSpellData['ru'][206475] = {name = "Рассечение Хаоса", additional_info = "[q]\"Удар Хаоса\" поражает всех находящихся поблизости противников, нанося им 10% дополнительного урона."}
