MultiLanguageSpellData['ru'][206923] = {name = "Извержение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Взывает к силе земли, вызывая неподалеку серию извержений. Каждый столп поражает цели в радиусе 5 м, нанося им урон от сил природы."}
