MultiLanguageSpellData['ru'][207143] = {name = "Выброс Бездны", additional_info = "Мгновенное действие\n[q]Энергия Бездны материализуется в пространстве и движется к игрокам, нанося 2566 ед. урона от темной магии сразу и дополнительно 2566 ед. урона от темной магии по прошествии 8 сек. Кроме того, через 8 сек. все пораженные игроки вызовут \"Извержение Бездны\"."}
MultiLanguageSpellData['ru'][207144] = {name = "Пригвожденная добыча", additional_info = "50 ед. концентрации Радиус действия: 100 м\n{Мгновенное действие} {Восстановление: 16 сек}\n[q]Приказывает вашему питомцу атаковать цель и нанести ей [1.5 * (0 + (Сила атаки дальнего боя * 1.632)) * 1 * (1 + Универсальность)] ед. урона. Если цель обездвижена, \"Пригвожденная добыча\" наносит на 200% больше урона, а скорость передвижения цели снижается на 70% на 3 сек."}
