MultiLanguageSpellData['ru'][207220] = {name = "Соратник: Ангус Железный Кулак", additional_info = "Мгновенное действие\n[q]Ангус Железный Кулак чуть ли не с рождения уже знал, что его призвание – сражаться. Он готов сойтись в бою с любым соперником и обрушить на него весь свой арсенал – приемы боевых искусств и стилей борьбы, захваты и точные удары руками и ногами."}
