MultiLanguageSpellData['ru'][207222] = {name = "Соратник: Хиро", additional_info = "Мгновенное действие\n[q]Хиро уже много лет странствует по свету, останавливаясь лишь в тавернах да забегаловках, чтобы пропустить очередной стаканчик. Затрапезный вид этого добряка весьма обманчив – дерется он так, что мало не покажется, особенно если выпьет."}
MultiLanguageSpellData['ru'][207223] = {name = "Соратник: Силара Стальная Песнь", additional_info = "Мгновенное действие\n[q]Силара Темносердная – таинственная странница, которая не любит распространяться о своем прошлом. Но ясно одно – ничто так не выводит ее из себя, как творящаяся в мире несправедливость. Любой, кто рассердит ее, быстро отведает смертоносных парных клинков."}
