MultiLanguageSpellData['ru'][207225] = {name = "Соратник: Эгира", additional_info = "Мгновенное действие\n[q]Эгира – врайкульский хмелевар, и сам Один держит ее на особом счету. Ее хмельные отвары поистине несравненны. Однако мало кто знает, что она еще и грозный боец. Можно сказать, она выросла на полях сражений, и никто из бросивших ей вызов так и не смог ее одолеть."}
