MultiLanguageSpellData['ru'][207228] = {name = "Искажение Ночного Колодца", additional_info = "Радиус действия: 500 м\nПрименение: 4 сек\n[q]Заклинатель искажает Ночной Колодец, нанося всем игрокам 733 ед. урона от тайной магии.\n\n С каждым применением этого заклинания урон от последующих искажений увеличивается на 20%."}
