MultiLanguageSpellData['ru'][207983] = {name = "Оскверняющее опустошение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ксавий создает сферы Кошмара, которые постепенно накапливают энергию и затем взрываются через 8 сек., нанося 45 ед. урона от темной магии и повышая уровень порчи всех игроков на 10 ед.\n При контакте с игроком сфера наносит ему 56 ед. урона от темной магии, повышает его уровень порчи на 0 ед. и исчезает, не взорвавшись."}
