MultiLanguageSpellData['ru'][209496] = {name = "[q3]Шип ужаса", additional_info = "Применение: 3.5 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток демонической стали (6), Кровь Саргераса (8), Инфернальная сера (2)\n[q]Изготовить шип ужаса.\nИсточник:\nХелия\nЗона:\nУтроба Душ (героический режим)\n\n[q3]Шип ужаса\nСтановится персональным при надевании\nУникальный использующийся\nРеликвия Кровь\n\n16\nТребуется"}
