MultiLanguageSpellData['ru'][210136] = {name = "Окаменение", additional_info = "Мгновенное действие\n[q]Цийлинь предпринимает попытку обратить своих противников в камень. При этом скорость их передвижения постепенно уменьшается. Противники, на которых эффект окаменения суммируется 100 раз, обратятся в камень и не смогут двигаться и совершать иные действия."}
MultiLanguageSpellData['ru'][210137] = {name = "Окаменение", additional_info = "Мгновенное действие\n[q]Цийлинь пытается превратить своих противников в камень, снижая их скорость передвижения по нарастающей. Противники, накопившие 100 эффекта:эффектов окаменения, обращаются в камень и не могут ни передвигаться, ни совершать какие-либо действия."}
