MultiLanguageSpellData['ru'][214577] = {name = "Энергия Ночного Колодца", additional_info = "{Мгновенное действие} {Восстановление: 20 сек}\n[q]Вы расходуете все заряды эффекта \"Энергия Ночного Колодца\" и получаете щит, поглощающий [ 911 * (1 + Универсальность)] ед. урона за каждый израсходованный эффект. Время действия щита – 15 сек."}
MultiLanguageSpellData['ru'][214579] = {name = "Рогатые гремучие змеи", additional_info = "Радиус действия: 40 м\nМгновенное действие Время восстановления 12 сек\n2 зарядов\nТребуется: Оружие дальнего боя\n[q]Вы выпускаете гремучих змей, которые ползут к цели по извилистой траектории, нанося ([65.52% of Attack Power]) ед. урона от сил природы всем задетым целям. Змеи не могут поразить одну и ту же цель дважды. Ко всем пораженным целям применяется эффект \"Уязвимость\".\n\nДает 35 ед. концентрации.\n\nЗаменяет \"Залп\"."}
