MultiLanguageSpellData['ru'][214651] = {name = "Кислотные обломки", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]От Скорпирона отваливаются кислотные фрагменты, создающие в точке падения обломок. Каждый фрагмент наносит 620 ед. урона от тайной магии всем противникам при падении и дополнительно 330 ед. урона от сил природы всем противникам раз в секунду.\n\n Заряды эффекта суммируются и действуют до тех пор, пока Скорпирон не сменит хроматический экзоскелет."}
